import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let seenEvent = false
  let lastTick = null
  const int = (v, field, least) => {
    if (!INT.test(v) || BigInt(v) < BigInt(least)) throw `${field} must be an integer of at least ${least}`
    return BigInt(v)
  }
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    try {
      const d = t[0]
      if (!['bucket', 'window', 'route', 'event'].includes(d)) throw `unknown directive ${d}`
      if (d !== 'event' && seenEvent) throw 'declarations must come before the first event'
      if (d === 'bucket') {
        if (t.length !== 5) throw 'expected bucket <name> <capacity> <refill> <per>'
        if (!NAME.test(t[1])) throw `invalid policy name ${t[1]}`
        const capacity = int(t[2], 'capacity', 1)
        const refill = int(t[3], 'refill', 0)
        const per = int(t[4], 'per', 1)
        if (policies.has(t[1])) throw `policy ${t[1]} is declared twice`
        policies.set(t[1], { kind: 'bucket', name: t[1], capacity, refill, per, state: new Map() })
      } else if (d === 'window') {
        if (t.length !== 4) throw 'expected window <name> <limit> <span>'
        if (!NAME.test(t[1])) throw `invalid policy name ${t[1]}`
        const limit = int(t[2], 'limit', 0)
        const span = int(t[3], 'span', 1)
        if (policies.has(t[1])) throw `policy ${t[1]} is declared twice`
        policies.set(t[1], { kind: 'window', name: t[1], limit, span, state: new Map() })
      } else if (d === 'route') {
        if (t.length < 3) throw 'expected route <prefix> <policy>...'
        if (!NAME.test(t[1])) throw `invalid route prefix ${t[1]}`
        if (routes.has(t[1])) throw `prefix ${t[1]} is routed twice`
        const ps = t.slice(2).map((n) => {
          if (!policies.has(n)) throw `unknown policy ${n}`
          return policies.get(n)
        })
        routes.set(t[1], ps)
      } else {
        if (t.length !== 3) throw 'expected event <tick> <key>'
        const tick = int(t[1], 'tick', 0)
        if (!NAME.test(t[2])) throw `invalid key ${t[2]}`
        if (lastTick !== null && tick < lastTick) throw `tick ${tick} is before tick ${lastTick}`
        lastTick = tick
        seenEvent = true
        events.push({ tick, key: t[2] })
      }
    } catch (e) {
      if (typeof e !== 'string') throw e
      throw new Fail(`error: line ${i + 1}: ${e}`)
    }
  }
  return { routes, events }
}

function advance(p, key, tick) {
  let s = p.state.get(key)
  if (p.kind === 'bucket') {
    // tokens are stored scaled by `per` so fractions stay exact
    if (!s) {
      s = { v: p.capacity * p.per, last: tick }
      p.state.set(key, s)
    }
    s.v += p.refill * (tick - s.last)
    const cap = p.capacity * p.per
    if (s.v > cap) s.v = cap
    s.last = tick
  } else {
    if (!s) {
      s = []
      p.state.set(key, s)
    }
    const cut = tick - p.span
    while (s.length && s[0] <= cut) s.shift()
  }
  return s
}

try {
  const { routes, events } = parse(readFileSync(0, 'utf8'))
  const out = []
  const counts = new Map()
  let ta = 0
  let td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const [prefix, ps] of routes) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
    }
    const ps = best === null ? [] : routes.get(best)
    const states = ps.map((p) => advance(p, key, tick))
    let denied = null
    for (let i = 0; i < ps.length && !denied; i++) {
      const p = ps[i]
      const ok = p.kind === 'bucket' ? states[i].v >= p.per : BigInt(states[i].length) < p.limit
      if (!ok) denied = p
    }
    if (!denied) {
      ps.forEach((p, i) => {
        if (p.kind === 'bucket') states[i].v -= p.per
        else states[i].push(tick)
      })
    }
    const c = counts.get(key) || { a: 0, d: 0 }
    counts.set(key, c)
    if (denied) { c.d++; td++ } else { c.a++; ta++ }
    out.push(denied ? `${tick} ${key} deny ${denied.name}` : `${tick} ${key} allow`)
  }
  if (mode === 'replay') {
    if (out.length) process.stdout.write(out.join('\n') + '\n')
  } else {
    const keys = [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    const lines = keys.map((k) => `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}`)
    lines.push(`total allowed=${ta} denied=${td}`)
    process.stdout.write(lines.join('\n') + '\n')
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
